draw((3.5,0)--(2.5,0)..(3.5,0)+dir(135)..(3.5,1)--(3.5,0)--cycle,dashed);

draw((-1.5,0)--(4,0),linewidth(2));

label("P",(-1.5,0),W);
label("A",(-1,0),S);
label("B",(0,0),S);
label("C",(0,1),N);

